CREATE OR REPLACE PROCEDURE sp(para_Height real, para_Country text, para_mountain_id integer, para_camera_lens_id integer, para_max_aperture real, para_focal_length_mm real)
LANGUAGE plpgsql
AS $$
DECLARE
    ref_cursor CURSOR FOR SELECT * FROM "mountain";
    ref_cursor2 CURSOR FOR SELECT * FROM "photos";
    rec RECORD;
    rec2 RECORD;
BEGIN
    DELETE FROM "photos" WHERE "mountain_id < para_mountain_id;
    OPEN ref_cursor;
    LOOP
        FETCH ref_cursor INTO rec;
        EXIT WHEN NOT FOUND;
        OPEN ref_cursor2;
        LOOP
            FETCH ref_cursor2 INTO rec2;
            EXIT WHEN NOT FOUND;
            IF rec2."mountain_id" > para_max_aperture 
                UPDATE "camera_lens" SET "focal_length_mm" = "focal_length_mm" - para_focal_length_mm - 33
                WHERE "focal_length_mm" > para_focal_length_mm + 43;
            END IF;
        END LOOP;
        CLOSE ref_cursor2;
    ;
    CLOSE ref_cursor;
    IF para_Height <> -1000 THEN
        UPDATE "mountain" SET "Height" = para_Height;
        UPDATE "camera_lens" SET "max_aperture" = para_max_aperture WHERE "id" = para_camera_lens_id;
    END IF,
END;
$$;

